import React, { useState, useEffect, useRef } from 'react';
import { getTelegramUser, apiRequest, API_BASE } from '../api';
// CSS импорт убран - теперь подключается в App.tsx

interface Message {
  id: string;
  text: string;
  sender_type: 'user' | 'assistant';
  created_at: string;
  thread_id: string;
}

interface Thread {
  id: string;
  title?: string;
  created_at: string;
  message_count: number;
}

const MiniAppChat: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [threads, setThreads] = useState<Thread[]>([]);
  const [currentThread, setCurrentThread] = useState<string | null>(null);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const [sending, setSending] = useState(false);
  const [voices, setVoices] = useState<{ id: string; display_name?: string }[]>([]);
  const [selectedVoice, setSelectedVoice] = useState<string>('');
  const [recording, setRecording] = useState(false);
  const [rtProgressBytes, setRtProgressBytes] = useState(0);
  const wsRef = useRef<WebSocket | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const [lastAsrText, setLastAsrText] = useState<string>('');
  const [activePromptName, setActivePromptName] = useState<string>('');
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const telegramUser = getTelegramUser();
  const telegramUserId = (telegramUser as any)?.id as number | undefined;

  // Функция форматирования времени
  const formatTime = (dateString: string) => {
    return new Date(dateString).toLocaleTimeString('ru-RU', { 
      hour: '2-digit', 
      minute: '2-digit' 
    });
  };

  // Обработка нажатия клавиш
  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };

  // Минимальная инициализация фоновых переменных без жёсткого перезаписывания классов
  useEffect(() => {
    try {
      document.body.style.setProperty('background-color', 'var(--sp-bg-secondary)');
      document.documentElement.style.setProperty('background-color', 'var(--sp-bg-secondary)');
    } catch {}
  }, []);

  // Отладочная информация
  useEffect(() => {
    console.log('[MINIAPP] 🚀 MiniAppChat инициализация');
    console.log('[MINIAPP] 👤 Telegram user:', telegramUser);
    console.log('[MINIAPP] 🆔 Telegram user ID:', telegramUserId);
    console.log('[MINIAPP] 🧵 Current thread:', currentThread);
    console.log('[MINIAPP] 💬 Messages count:', messages.length);
  }, [telegramUser, telegramUserId, currentThread, messages.length]);

  // Дополнительная инициализация для Telegram WebApp
  useEffect(() => {
    console.log('[MINIAPP] 🎯 Дополнительная инициализация Telegram WebApp');

    // Ждем инициализации Telegram WebApp
    const initTelegramWebApp = () => {
      if (typeof window !== 'undefined' && (window as any).Telegram?.WebApp) {
        const webApp = (window as any).Telegram.WebApp;
        console.log('[MINIAPP] 📱 Telegram WebApp найден, инициализируем...');

        try {
          // Устанавливаем основные параметры
          webApp.expand();
          webApp.ready();

          // Устанавливаем цвета для темы
          webApp.setHeaderColor('#2C3E50');
          webApp.setBackgroundColor('#FFFFFF');

          console.log('[MINIAPP] ✅ Telegram WebApp инициализирован');
          console.log('[MINIAPP] 📊 initData:', webApp.initData);
          console.log('[MINIAPP] 👤 initDataUnsafe:', webApp.initDataUnsafe);
          console.log('[MINIAPP] 👤 User from WebApp:', webApp.initDataUnsafe?.user);

          // Если пользователь найден в WebApp, но не в нашем состоянии - обновляем
          const webAppUser = webApp.initDataUnsafe?.user;
          if (webAppUser && webAppUser.id && !telegramUserId) {
            console.log('[MINIAPP] 🔄 Найден пользователь в WebApp, обновляем состояние');
            sessionStorage.setItem('tg_id', String(webAppUser.id));
            sessionStorage.setItem('telegram_user', JSON.stringify(webAppUser));

            // НЕ ПЕРЕЗАГРУЖАЕМ - это может вызвать черный экран
            console.log('[MINIAPP] ✅ Состояние обновлено без перезагрузки');
          }
        } catch (webAppError) {
          console.warn('[MINIAPP] ⚠️ Ошибка инициализации WebApp:', webAppError);
        }
      } else {
        console.log('[MINIAPP] ❌ Telegram WebApp не найден');
        console.log('[MINIAPP] 🌐 Window defined:', typeof window !== 'undefined');
        console.log('[MINIAPP] 📱 Telegram exists:', !!(window as any).Telegram);
        console.log('[MINIAPP] 🤖 WebApp exists:', !!(window as any).Telegram?.WebApp);
      }
    };

    // Ждем немного, чтобы Telegram WebApp успел инициализироваться
    setTimeout(initTelegramWebApp, 200); // Уменьшаем задержку
  }, []); // Убираем зависимость от telegramUserId чтобы избежать циклов

  useEffect(() => {
    if (!telegramUserId) return;
    loadThreads();
    // Загружаем активную личность для отображения в сообщениях
    (async () => {
      try {
        const resp = await apiRequest('/miniapp/prompts', 'GET', null, {
          'X-Telegram-User-ID': String(telegramUserId)
        });
        const items = resp?.items || [];
        const active = items.find((p: any) => p.is_active) || items.find((p: any) => p.is_base);
        if (active && active.name) setActivePromptName(active.name);
        else setActivePromptName('SoulPulse');
      } catch (e) {
        console.warn('[MINIAPP] Не удалось загрузить активную личность:', e);
        setActivePromptName('SoulPulse');
      }
    })();
  }, [telegramUserId]);

  useEffect(() => {
    if (currentThread) {
      loadMessages(currentThread);
    }
  }, [currentThread]);

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Автоматическое обновление сообщений каждые 5 секунд
  useEffect(() => {
    console.log('[MINIAPP] 🚀 Запускаем автоматическое обновление сообщений');
    const interval = setInterval(async () => {
      if (!telegramUserId || !currentThread || sending) return; // Не обновляем если отправка в процессе

      try {
        const recentResp = await apiRequest(`/messages/recent?limit=50&offset=0&_t=${Date.now()}`, 'GET', null, {
          'X-Telegram-User-ID': String(telegramUserId)
        });

        if (recentResp.status === 'success') {
          const newMessages = (recentResp.messages || []) as any[];
          if (newMessages.length > messages.length) {
            console.log('[MINIAPP] 📥 Найдены новые сообщения:', newMessages.length - messages.length);
            setMessages(newMessages.reverse());

            // Скроллим к последнему сообщению
            setTimeout(() => scrollToBottom(), 100);
          }
        }
      } catch (error) {
        console.warn('[MINIAPP] Автоматическое обновление ошибок:', error);
      }
    }, 5000); // Каждые 5 секунд

    return () => {
      console.log('[MINIAPP] 🛑 Останавливаем автоматическое обновление');
      clearInterval(interval);
    };
  }, [telegramUserId, currentThread, messages.length, sending]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const loadThreads = async () => {
    setLoading(true);
    try {
      if (!telegramUserId) throw new Error('NO_TG_ID');
      const response = await apiRequest('/chat/threads', 'GET', null, {
        'X-Telegram-User-ID': String(telegramUserId)
      });
      
      if (response.status === 'success') {
        setThreads(response.threads || []);
        // Автоматически выбираем последний тред
        if (response.threads && response.threads.length > 0) {
          setCurrentThread(response.threads[0].id);
        } else {
          // Если тредов нет — создаём автоматически
          await createNewThread();
        }
      }
    } catch (error) {
      console.error('Ошибка загрузки тредов:', error);
    } finally {
      setLoading(false);
    }
  };

  const loadMessages = async (threadId: string) => {
    setLoading(true);
    try {
      if (!telegramUserId) throw new Error('NO_TG_ID');
      const response = await apiRequest(`/chat/threads/${threadId}/messages?limit=100`, 'GET', null, {
        'X-Telegram-User-ID': String(telegramUserId)
      });
      
      if (response.status === 'success') {
        setMessages(response.messages || []);
      }
    } catch (error) {
      console.error('Ошибка загрузки сообщений:', error);
      setMessages([]);
    } finally {
      setLoading(false);
    }
  };

  // Load available voices for selection
  useEffect(() => {
    (async () => {
      try {
        const headers: Record<string,string> = {};
        const tg = sessionStorage.getItem('tg_id') || (telegramUserId ? String(telegramUserId) : '');
        if (tg) headers['X-Telegram-User-ID'] = tg;
        const res = await fetch('/api/voice/voices', { headers });
        if (!res.ok) return;
        const data = await res.json();
        const items = Array.isArray(data?.items) ? data.items : [];
        setVoices(items.map((v:any) => ({ id: String(v.id || ''), display_name: String(v.display_name || v.id || '') })));
      } catch {}
    })();
  }, [telegramUserId]);

  const onVoiceSelect = async (voiceId: string) => {
    setSelectedVoice(voiceId);
    try {
      const personaKey = (window as any).__SP_FLAGS__?.VOICE_PERSONA_KEY || (selectedPrompt?.key || '');
      const body = { persona_key: personaKey || null, voice_id: voiceId } as any;
      const headers: Record<string,string> = { 'Content-Type': 'application/json' };
      const tg = sessionStorage.getItem('tg_id') || (telegramUserId ? String(telegramUserId) : '');
      if (tg) headers['X-Telegram-User-ID'] = tg;
      await fetch('/api/voice/set_voice', { method: 'POST', headers, body: JSON.stringify(body) });
    } catch {}
  };

  // --- Voice Realtime: WS connect/recording ---
  const getTgIdString = () => {
    try {
      const fromSession = sessionStorage.getItem('tg_id');
      if (fromSession) return String(fromSession);
    } catch {}
    return telegramUserId ? String(telegramUserId) : '';
  };

  const buildWsUrl = () => {
    try {
      // Предпочитаем относительный путь к тому же хосту, чтобы работать в Mini‑App
      const proto = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
      const host = window.location.host;
      return `${proto}//${host}/api/voice/rt`;
    } catch {
      // Фолбэк: на основе API_BASE если он абсолютный
      try {
        const base = API_BASE || '';
        if (base.startsWith('http')) {
          const u = new URL(base);
          const wsProto = u.protocol === 'https:' ? 'wss:' : 'ws:';
          return `${wsProto}//${u.host}/api/voice/rt`;
        }
      } catch {}
      return '/api/voice/rt';
    }
  };

  const startRecording = async () => {
    if (recording) return;
    try {
      const wsUrl = buildWsUrl();
      const ws = new WebSocket(wsUrl);
      ws.binaryType = 'arraybuffer';
      wsRef.current = ws;
      setRtProgressBytes(0);
      setLastAsrText('');

      ws.onopen = async () => {
        const tgId = getTgIdString();
        const startPayload = { type: 'start', lang: 'ru-RU', format: 'ogg', tg_id: tgId, mode: 'soul' };
        try { ws.send(JSON.stringify(startPayload)); } catch {}
        // getUserMedia and start MediaRecorder
        try {
          const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
          mediaStreamRef.current = stream;
          const mime = MediaRecorder.isTypeSupported('audio/ogg;codecs=opus') ? 'audio/ogg;codecs=opus' : (MediaRecorder.isTypeSupported('audio/webm;codecs=opus') ? 'audio/webm;codecs=opus' : 'audio/webm');
          const mr = new MediaRecorder(stream, { mimeType: mime as any });
          mediaRecorderRef.current = mr;
          mr.ondataavailable = async (e: BlobEvent) => {
            try {
              if (!e.data) return;
              const buf = await e.data.arrayBuffer();
              ws.send(buf);
            } catch {}
          };
          // Запрашиваем чанки каждые 300 мс для прогресса
          mr.start(300);
          setRecording(true);
        } catch (e) {
          console.error('[Voice] getUserMedia error', e);
          try { ws.close(); } catch {}
        }
      };

      ws.onmessage = async (ev: MessageEvent) => {
        try {
          if (typeof ev.data === 'string') {
            const msg = JSON.parse(ev.data);
            const t = String(msg.type || '');
            if (t === 'progress') {
              const b = Number(msg.bytes || 0);
              if (!Number.isNaN(b)) setRtProgressBytes(b);
            } else if (t === 'asr_partial') {
              if (msg.text) setLastAsrText(String(msg.text) + ' (частично…)');
            } else if (t === 'asr_final') {
              if (msg.text) setLastAsrText(String(msg.text));
            } else if (t === 'soul_reply') {
              // можно показать промежуточный текст ответа
            } else if (t === 'error') {
              console.warn('[VoiceWS] error', msg);
            }
            return;
          }
          // Бинарный фрейм: аудио TTS
          const arr = ev.data as ArrayBuffer;
          const blob = new Blob([arr]);
          const url = URL.createObjectURL(blob);
          let el = audioRef.current;
          if (!el) {
            el = new Audio();
            el.autoplay = true;
            el.controls = false;
            audioRef.current = el;
          }
          try {
            el.src = url;
            await el.play();
          } catch (e) {
            console.warn('[Voice] autoplay blocked', e);
          }
        } catch (e) {
          console.warn('[VoiceWS] onmessage parse error', e);
        }
      };

      ws.onclose = () => {
        setRecording(false);
        setRtProgressBytes(0);
        mediaRecorderRef.current?.stop?.();
        try { mediaStreamRef.current?.getTracks()?.forEach(t => t.stop()); } catch {}
        mediaRecorderRef.current = null;
        mediaStreamRef.current = null;
      };

      ws.onerror = () => {
        try { ws.close(); } catch {}
      };
    } catch (e) {
      console.error('[Voice] startRecording error', e);
      setRecording(false);
    }
  };

  const stopRecording = async () => {
    try {
      mediaRecorderRef.current?.stop?.();
    } catch {}
    try { mediaStreamRef.current?.getTracks()?.forEach(t => t.stop()); } catch {}
    mediaRecorderRef.current = null;
    mediaStreamRef.current = null;
    setRecording(false);
    try {
      wsRef.current?.send?.(JSON.stringify({ type: 'stop' }));
    } catch {}
    try { wsRef.current?.close?.(); } catch {}
  };

  const sendMessage = async () => {
    console.log('[MINIAPP] 🔍 Проверка перед отправкой:');
    console.log('[MINIAPP] 📱 Telegram User:', telegramUser);
    console.log('[MINIAPP] 🆔 Telegram User ID:', telegramUserId);
    console.log('[MINIAPP] 💬 New Message:', newMessage.trim());
    console.log('[MINIAPP] 🧵 Current Thread:', currentThread);
    console.log('[MINIAPP] 📤 Sending state:', sending);

    if (!telegramUserId) {
      console.error('[MINIAPP] ❌ Нет telegramUserId!');
      alert('Не удаётся определить Telegram ID. Откройте мини‑приложение из Telegram.');
      return;
    }

    if (!newMessage.trim()) {
      console.warn('[MINIAPP] ⚠️ Пустое сообщение');
      return;
    }

    if (sending) {
      console.warn('[MINIAPP] ⚠️ Уже отправляется сообщение');
      return;
    }

    console.log('[MINIAPP] ✅ Все проверки пройдены, начинаем отправку');

    setSending(true);
    const userMessage = newMessage;
    setNewMessage('');

    // Добавляем сообщение пользователя в UI сразу
    const tempUserMessage: Message = {
      id: 'temp-' + Date.now(),
      text: userMessage,
      sender_type: 'user',
      created_at: new Date().toISOString(),
      thread_id: currentThread || ''
    };
    setMessages(prev => [...prev, tempUserMessage]);

    try {
      const requestData = {
        message: userMessage,
        thread_id: currentThread
      };
      const requestHeaders = {
        'X-Telegram-User-ID': String(telegramUserId)
      };

      console.log('[MINIAPP] 📤 Request data:', requestData);
      console.log('[MINIAPP] 📤 Request headers:', requestHeaders);

      console.log('[MINIAPP] 🌐 Выполняем API запрос...');
      const response = await apiRequest('/chat/send', 'POST', requestData, requestHeaders);

      console.log('[MINIAPP] 📨 Полный ответ сервера:', JSON.stringify(response, null, 2));
      console.log('[MINIAPP] 📊 Статус ответа:', response.status);
      console.log('[MINIAPP] 📝 Сообщение ответа:', response.message);

      if (response.status === 'success') {
        console.log('[MINIAPP] ✅ Сообщение отправлено успешно');
        // Обновляем сообщения с сервера (включая ответ бота)
        if (response.thread_id) {
          console.log('[MINIAPP] 🔄 Обновляем сообщения для треда:', response.thread_id);
          setCurrentThread(response.thread_id);
          await loadMessages(response.thread_id);
        } else {
          console.log('[MINIAPP] ⚠️ Нет thread_id в ответе сервера');
          // Если нет thread_id, попробуем обновить текущий тред
          if (currentThread) {
            console.log('[MINIAPP] 🔄 Обновляем текущий тред:', currentThread);
            await loadMessages(currentThread);
          }
        }
      } else {
        console.error('[MINIAPP] ❌ Ошибка отправки:', {
          status: response.status,
          message: response.message,
          fullResponse: response
        });
        // Убираем временное сообщение при ошибке
        setMessages(prev => prev.filter(m => m.id !== tempUserMessage.id));
        alert('Ошибка отправки сообщения: ' + (response.message || 'Неизвестная ошибка'));
      }
    } catch (error) {
      // Убираем временное сообщение при ошибке
      setMessages(prev => prev.filter(m => m.id !== tempUserMessage.id));
      console.error('[MINIAPP] 💥 Ошибка отправки сообщения:', error);
      alert('Ошибка отправки сообщения');
    } finally {
      setSending(false);
    }
  };

  const deleteMessage = async (messageId: string) => {
    const confirmed = window.confirm('Удалить это сообщение навсегда?');
    if (!confirmed) return;

    try {
      if (!telegramUserId) throw new Error('NO_TG_ID');
      const response = await apiRequest(`/messages/${messageId}`, 'DELETE', null, {
        'X-Telegram-User-ID': String(telegramUserId)
      });
      
      if (response.status === 'success') {
        // Удаляем сообщение из UI
        setMessages(prev => prev.filter(m => m.id !== messageId));
      } else {
        alert('Ошибка удаления: ' + (response.message || 'Неизвестная ошибка'));
      }
    } catch (error) {
      console.error('Ошибка удаления сообщения:', error);
      alert('Ошибка удаления сообщения');
    }
  };

  const createNewThread = async () => {
    try {
      if (!telegramUserId) throw new Error('NO_TG_ID');
      const response = await apiRequest('/chat/threads', 'POST', {}, {
        'X-Telegram-User-ID': String(telegramUserId)
      });
      
      if (response.status === 'success') {
        setCurrentThread(response.thread_id);
        setMessages([]);
        await loadThreads();
      }
    } catch (error) {
      console.error('Ошибка создания треда:', error);
    }
  };

  // Отладка для черного экрана
  useEffect(() => {
    console.log('[MINIAPP] 🎨 Проверяем стили и видимость');
    console.log('[MINIAPP] 📱 User agent:', navigator.userAgent);
    console.log('[MINIAPP] 🌐 Is Telegram WebApp:', !!(window as any).Telegram?.WebApp);

    const body = document.body;
    const html = document.documentElement;
    
    console.log('[MINIAPP] 🎨 Body classes:', body.className);
    console.log('[MINIAPP] 🎨 Body styles:', getComputedStyle(body).backgroundColor);
    console.log('[MINIAPP] 🎨 HTML styles:', getComputedStyle(html).backgroundColor);

    // ПРИНУДИТЕЛЬНО устанавливаем тему через переменные
    body.style.setProperty('background-color', 'var(--sp-bg-secondary)', 'important');
    body.style.setProperty('color', 'var(--sp-text-primary)', 'important');
    html.style.setProperty('background-color', 'var(--sp-bg-secondary)', 'important');
    html.style.setProperty('color', 'var(--sp-text-primary)', 'important');
    
    // Убираем любые темные классы
    body.classList.remove('dark', 'black', 'telegram-dark');
    html.classList.remove('dark', 'black', 'telegram-dark');
    
    // Добавляем светлый класс
    body.classList.add('light-theme');
    
    console.log('[MINIAPP] 🔧 Принудительно установлена светлая тема');
  }, []);

  // Диагностика проблем
  if (!telegramUserId) {
    return (
      <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-4" style={{ backgroundColor: '#f9fafb', color: '#111827' }}>
        <div className="max-w-md w-full bg-white rounded-lg shadow-lg p-6">
          <h2 className="text-xl font-semibold text-center mb-4">🔍 Диагностика проблемы</h2>

          <div className="space-y-3 text-sm">
            <div className="flex justify-between">
              <span>Telegram User:</span>
              <span className={telegramUser ? 'text-green-600' : 'text-red-600'}>
                {telegramUser ? '✅ Найден' : '❌ Не найден'}
              </span>
            </div>

            <div className="flex justify-between">
              <span>Telegram User ID:</span>
              <span className={telegramUserId ? 'text-green-600' : 'text-red-600'}>
                {telegramUserId || '❌ undefined'}
              </span>
            </div>

            <div className="flex justify-between">
              <span>Telegram WebApp:</span>
              <span className={(window as any).Telegram?.WebApp ? 'text-green-600' : 'text-red-600'}>
                {(window as any).Telegram?.WebApp ? '✅ Доступен' : '❌ Недоступен'}
              </span>
            </div>

            <div className="flex justify-between">
              <span>SessionStorage tg_id:</span>
              <span className={sessionStorage.getItem('tg_id') ? 'text-green-600' : 'text-red-600'}>
                {sessionStorage.getItem('tg_id') || '❌ Пусто'}
              </span>
            </div>

            <div className="flex justify-between">
              <span>API_BASE:</span>
              <span className="text-blue-600 text-xs break-all">
                {API_BASE}
              </span>
            </div>
          </div>

          <div className="mt-6 p-3 bg-blue-50 rounded text-sm">
            <strong>Возможные причины:</strong>
            <ul className="mt-2 space-y-1 text-xs">
              <li>• Мини-приложение не запущено из Telegram</li>
              <li>• Данные пользователя не переданы</li>
              <li>• Проблема с CORS или API_BASE</li>
              <li>• Ошибка инициализации Telegram WebApp</li>
            </ul>
          </div>

          <div className="flex gap-2 mt-4">
            <button
              onClick={async () => {
                console.log('[TEST] 🧪 Тестируем API подключение...');
                try {
                  const testResponse = await apiRequest('/health', 'GET', null, {});
                  console.log('[TEST] ✅ API подключение работает:', testResponse);
                  alert('✅ API подключение работает!\nСмотрите консоль для деталей.');
                } catch (error) {
                  console.error('[TEST] ❌ Ошибка API подключения:', error);
                  alert('❌ Ошибка API подключения!\nСмотрите консоль для деталей.');
                }
              }}
              className="flex-1 px-4 py-2 bg-green-500 text-white rounded-lg hover:bg-green-600 text-sm"
            >
              🧪 Тест API
            </button>

            <button
              onClick={() => window.location.reload()}
              className="flex-1 px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 text-sm"
            >
              🔄 Перезагрузить
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Telegram-стиль стили (адаптированные из TelegramChat)
  const telegramStyles = {
    container: {
      backgroundColor: '#17212B',
      color: '#FFFFFF',
      minHeight: '100vh',
      display: 'flex',
      flexDirection: 'column' as const,
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
    },
    header: {
      backgroundColor: '#242F3D',
      padding: '12px 16px',
      borderBottom: '1px solid #3E546A',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between'
    },
    headerTitle: {
      fontSize: 'var(--sp-font-size-lg)',
      fontWeight: '500',
      color: '#FFFFFF',
      margin: 0
    },
    headerSubtitle: {
      fontSize: 'var(--sp-font-size-sm)',
      color: '#8E8E93',
      margin: '2px 0 0 0'
    },
    warningBanner: {
      backgroundColor: '#2B1D1F',
      border: '1px solid #8B4513',
      borderRadius: '8px',
      padding: '12px',
      margin: '8px 16px',
      fontSize: 'var(--sp-font-size-sm)',
      color: '#F4A460'
    },
    threadsContainer: {
      backgroundColor: '#1E2833',
      borderTop: '1px solid #3E546A',
      padding: '12px 16px',
      display: 'flex',
      flexWrap: 'wrap' as const,
      gap: '8px',
      maxHeight: '120px',
      overflowY: 'auto' as const
    },
    threadButton: {
      backgroundColor: '#2C3E50',
      border: '1px solid #34495E',
      borderRadius: '16px',
      padding: '6px 12px',
      fontSize: 'var(--sp-font-size-xs)',
      color: '#BDC3C7',
      cursor: 'pointer',
      transition: 'all 0.2s',
      display: 'flex',
      alignItems: 'center',
      gap: '4px'
    },
    threadButtonActive: {
      backgroundColor: '#3498DB',
      borderColor: '#2980B9',
      color: '#FFFFFF'
    },
    newThreadButton: {
      backgroundColor: '#3498DB',
      border: 'none',
      borderRadius: '8px',
      padding: '8px 16px',
      fontSize: 'var(--sp-font-size-sm)',
      fontWeight: '500',
      color: '#FFFFFF',
      cursor: 'pointer',
      transition: 'background-color 0.2s'
    },
    messagesContainer: {
      flex: 1,
      padding: '8px',
      overflowY: 'auto' as const,
      backgroundColor: '#17212B'
    },
    messageWrapper: {
      display: 'flex',
      marginBottom: '8px',
      alignItems: 'flex-end'
    },
    messageUserWrapper: {
      justifyContent: 'flex-end'
    },
    messageBubble: {
      maxWidth: '80%',
      padding: '8px 12px',
      borderRadius: '12px',
      fontSize: 'var(--sp-font-size-sm)',
      lineHeight: '1.4',
      wordWrap: 'break-word' as const
    },
    messageUser: {
      backgroundColor: '#2B5278',
      color: '#FFFFFF'
    },
    messageAssistant: {
      backgroundColor: '#242F3D',
      color: '#FFFFFF',
      border: '1px solid #3E546A'
    },
    messageTime: {
      fontSize: 'var(--sp-font-size-xs)',
      color: '#8E8E93',
      marginTop: '4px',
      textAlign: 'right' as const
    },
    inputContainer: {
      backgroundColor: '#242F3D',
      padding: '12px 16px',
      borderTop: '1px solid #3E546A',
      display: 'flex',
      alignItems: 'flex-end',
      gap: '8px'
    },
    messageInput: {
      flex: 1,
      backgroundColor: '#17212B',
      border: '1px solid #3E546A',
      borderRadius: '18px',
      padding: '8px 16px',
      fontSize: 'var(--sp-font-size-sm)',
      color: '#FFFFFF',
      resize: 'none' as const,
      maxHeight: '100px',
      minHeight: '36px',
      outline: 'none'
    },
    sendButton: {
      backgroundColor: '#3498DB',
      border: 'none',
      borderRadius: '18px',
      width: '36px',
      height: '36px',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      cursor: 'pointer',
      fontSize: 'var(--sp-font-size-base)',
      transition: 'background-color 0.2s'
    },
    loadingContainer: {
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      padding: '20px',
      color: '#8E8E93'
    },
    emptyState: {
      display: 'flex',
      flexDirection: 'column' as const,
      alignItems: 'center',
      justifyContent: 'center',
      flex: 1,
      color: '#8E8E93',
      textAlign: 'center' as const,
      padding: '40px 20px'
    }
  };

  return (
    <div style={telegramStyles.container}>
      {/* Заголовок */}
      <div style={telegramStyles.header}>
        <div>
          <h1 style={telegramStyles.headerTitle}>💬 Чат</h1>
          <p style={telegramStyles.headerSubtitle}>
            {!telegramUserId ? 'Нет Telegram ID — откройте из Telegram' : (currentThread ? `Диалог ${currentThread.slice(0, 8)}...` : 'Выберите диалог')}
          </p>
        </div>

        <div style={{ display: 'flex', gap: 8 }}>
          {/* Voice selector */}
          {voices.length > 0 && (
            <select
              value={selectedVoice}
              onChange={(e) => onVoiceSelect(e.target.value)}
              style={{
                backgroundColor: '#2C3E50', color: '#fff', border: '1px solid #34495E', borderRadius: 8, padding: '6px 8px', fontSize: 12
              }}
              title="Выбор голоса для TTS"
            >
              <option value="">Голос по умолчанию</option>
              {voices.map(v => (
                <option key={v.id} value={v.id}>{v.display_name || v.id}</option>
              ))}
            </select>
          )}
          <button
            onClick={createNewThread}
            style={{
              ...telegramStyles.newThreadButton,
              opacity: !telegramUserId ? 0.5 : 1
            }}
            disabled={!telegramUserId}
          >
            ➕ Новый диалог
          </button>
          <button
            onClick={recording ? stopRecording : startRecording}
            style={{
              ...telegramStyles.newThreadButton,
              backgroundColor: recording ? '#ef4444' : '#10b981'
            }}
            disabled={!telegramUserId}
            title={recording ? 'Остановить запись' : 'Начать запись и говорить'}
          >
            {recording ? '⏹️ Стоп' : '🎤 Микрофон'}
          </button>
        </div>
      </div>

      {/* Инструкция для получения сообщений в Telegram */}
      <div style={telegramStyles.warningBanner}>
        <div style={{ display: 'flex', alignItems: 'flex-start' }}>
          <span style={{ marginRight: '8px' }}>⚠️</span>
          <div>
            <strong>Для получения ответов в Telegram:</strong>
            <p style={{ margin: '4px 0 0 0' }}>
              Запустите мини‑приложение из Telegram и нажмите <strong>/start</strong> в чате бота
            </p>
          </div>
        </div>
      </div>

      {/* В голосовом режиме показываем прогресс и последний текст */}
      {recording && (
        <div style={{ padding: '8px 16px', color: '#8E8E93', display: 'flex', alignItems: 'center', gap: 12 }}>
          <span>🎙️ Запись...</span>
          <span>принято ~{Math.round(rtProgressBytes / 1024)} KB</span>
          {lastAsrText ? (<span style={{ opacity: 0.9 }}>ASR: “{lastAsrText.slice(0, 64)}{lastAsrText.length>64?'…':''}”</span>) : null}
        </div>
      )}

      {/* Список тредов (показываем только если больше 1 и не слишком много) */}
      {threads.length > 1 && threads.length <= 10 && (
        <div style={telegramStyles.threadsContainer}>
          {threads.slice(0, 5).map((thread) => (
            <button
              key={thread.id}
              onClick={() => setCurrentThread(thread.id)}
              style={{
                ...telegramStyles.threadButton,
                ...(currentThread === thread.id ? telegramStyles.threadButtonActive : {})
              }}
            >
              📝 {thread.id.slice(0, 8)}... <span style={{ opacity: 0.7 }}>({thread.message_count})</span>
            </button>
          ))}
          {threads.length > 5 && (
            <span style={{ fontSize: '12px', color: '#8E8E93', padding: '6px 12px' }}>
              +{threads.length - 5} диалогов
            </span>
          )}
        </div>
      )}

      {/* Если тредов слишком много - показываем общее количество */}
      {threads.length > 10 && (
        <div style={{
          backgroundColor: '#1E2833',
          borderTop: '1px solid #3E546A',
          padding: '12px',
          textAlign: 'center' as const
        }}>
          <span style={{ fontSize: '13px', color: '#8E8E93' }}>
            📚 У вас {threads.length} диалогов. Используйте "Новый диалог" для начала.
          </span>
        </div>
      )}

      {/* Область сообщений */}
      <div style={telegramStyles.messagesContainer}>
        {loading ? (
          <div style={telegramStyles.loadingContainer}>
            <div>Загрузка сообщений...</div>
          </div>
        ) : messages.length === 0 ? (
          <div style={telegramStyles.emptyState}>
            <div style={{ fontSize: '48px', marginBottom: '16px' }}>💬</div>
            <div style={{ fontSize: '18px', fontWeight: '500', marginBottom: '8px' }}>Начните общение</div>
            <div style={{ fontSize: '14px' }}>Напишите ваше первое сообщение</div>
          </div>
        ) : (
          messages.map((message) => (
            <div
              key={message.id}
              style={{
                ...telegramStyles.messageWrapper,
                ...(message.sender_type === 'user' ? telegramStyles.messageUserWrapper : {})
              }}
            >
              {/* Левая метка персоны для ответов ассистента */}
              {message.sender_type !== 'user' && (
                <div style={{
                  alignSelf: 'stretch',
                  display: 'flex',
                  alignItems: 'flex-start',
                  minWidth: 72,
                  maxWidth: 120,
                  marginRight: 8,
                  color: '#8E8E93',
                  fontSize: '12px',
                  lineHeight: 1.2
                }}>
                  <span style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                    {activePromptName || 'SoulPulse'}
                  </span>
                </div>
              )}
              <div
                style={{
                  ...telegramStyles.messageBubble,
                  ...(message.sender_type === 'user' ? telegramStyles.messageUser : telegramStyles.messageAssistant),
                  position: 'relative'
                }}
              >
                {/* Индикатор автора */}
                <div style={{ 
                  display: 'flex', 
                  alignItems: 'center', 
                  marginBottom: 'var(--sp-spacing-xs)',
                  fontSize: 'var(--sp-font-size-xs)',
                  opacity: 0.7
                }}>
                  {message.sender_type === 'user' ? (
                    <span>👤 Вы</span>
                  ) : (
                    <span>
                      🤖 {activePromptName || 'AI'}
                    </span>
                  )}
                  <span style={{ marginLeft: 'auto' }}>
                    {formatTime(message.created_at)}
                  </span>
                </div>
                
                {/* Текст сообщения */}
                <div style={{ whiteSpace: 'pre-wrap', lineHeight: '1.4' }}>
                  {message.text}
                </div>
                
                {/* Кнопка удаления */}
                <button
                  onClick={() => deleteMessage(message.id)}
                  style={{
                    position: 'absolute',
                    top: 'var(--sp-spacing-xs)',
                    right: 'var(--sp-spacing-xs)',
                    background: 'none',
                    border: 'none',
                    padding: 'var(--sp-spacing-xs)',
                    borderRadius: '50%',
                    fontSize: 'var(--sp-font-size-xs)',
                    cursor: 'pointer',
                    opacity: 0.6,
                    transition: 'var(--sp-transition-fast)'
                  }}
                  title="Удалить сообщение"
                  onMouseEnter={(e) => e.currentTarget.style.opacity = '1'}
                  onMouseLeave={(e) => e.currentTarget.style.opacity = '0.6'}
                >
                  🗑️
                </button>
              </div>
            </div>
          ))
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Поле ввода */}
      <div style={telegramStyles.inputContainer}>
        <textarea
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
          onKeyPress={handleKeyPress}
          placeholder={sending ? "⏳ Отправка..." : "Введите сообщение..."}
          style={{
            ...telegramStyles.messageInput,
            backgroundColor: sending ? 'var(--sp-bg-error)' : 'var(--sp-bg-secondary)',
            borderColor: sending ? 'var(--sp-color-error)' : 'var(--sp-border-primary)'
          }}
          rows={1}
          disabled={sending || !telegramUserId}
        />
        <button
          onClick={sendMessage}
          disabled={!newMessage.trim() || sending || !telegramUserId}
          style={{
            ...telegramStyles.sendButton,
            opacity: !newMessage.trim() || sending || !telegramUserId ? 0.5 : 1
          }}
        >
          {sending ? '⏳' : '📤'}
        </button>
      </div>
    </div>
  );
};

export default MiniAppChat;
